with latest as (select id, dept_name, location, budget from (select *, rank() over (partition by location, dept_name order by budget desc) as row_num from departments) t where row_num = 1) select dept_name, percentile_approx(budget, 0.95) as budget_p95, round(sum(budget) / nullif(count(case when dept_name = 'Marketing' then 1 end), 0), 2) as budget_per_marketing, count(*) as cnt from latest group by dept_name order by cnt;
